const $ = s => document.querySelector(s);
const root = '/assets/';
const label = (n,t) => `<div class="eyebrow"><span class="dot"></span>${n ? n+' / ' : ''}${t}</div>`;
const link = (url,t) => `<a class="text-link" href="${url}">${t}<span aria-hidden="true">↗</span></a>`;
const productionImages = ['P9240350.JPG','P9240354.JPG','P9240355.JPG','PC190266.JPG','PC190267.JPG','PC190268.JPG','PC190272.JPG','PC190282.JPG','vyroba1.JPG','vyroba10.jpg','vyroba11.jpg','vyroba2.jpg','vyroba3.jpg','vyroba4.jpg','vyroba5.jpg','vyroba6.jpg','vyroba7.jpg','vyroba8.jpg','vyroba9.jpg'];
let gallery = [], currentImage = 0, returnFocus;
const photo = (file,title,caption='Zákazková výroba') => `<button class="product-tile" data-photo="${file}" data-caption="${title}" aria-label="Zväčšiť: ${title}"><div class="photo"><img src="${root+file}" alt="${title}" loading="lazy" width="1024" height="768"></div><div class="photo-caption"><span>${title}</span><small>${caption} ↗</small></div></button>`;
const table = (heads,rows) => `<div class="table-scroll"><table><thead><tr>${heads.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const dataGroup = (title,content) => `<section class="data-group"><h2>${title}</h2><div>${content}</div></section>`;
const head = (crumb,title,description='') => `<div class="wrap"><section class="page-head"><div class="breadcrumb"><a href="/">Úvod</a><span>/</span><span>${crumb}</span></div><h1>${title}</h1>${description?`<p class="page-description">${description}</p>`:''}</section></div>`;
const cta = () => `<section class="contact-band"><div class="wrap contact-band-inner">${label('','Začnime spoluprácu')}<div><h2>Máte výkres.<br>My mu dáme <em>tvar.</em></h2><div class="cta-bottom"><p>Prejdime si vaše zadanie, výrobné možnosti a termín dodania. Osobne a konkrétne.</p><a class="circle-link" href="/kontakt/" aria-label="Kontaktovať UNIKOV">↗</a></div></div></div></section>`;
function home(){return `<section class="hero wrap"><div class="hero-topline">${label('','Strojárska výroba od roku 1995')}<div class="location">Dubnica nad Váhom, Slovensko</div></div><div class="hero-heading"><h1>Presnosť má<br>svoj <em>tvar.</em></h1><div class="hero-description"><p>Premieňame kov na diely, ktoré do seba zapadnú. Od vášho výkresu až po hotový celok.</p>${link('/vyroba/','Spoznajte našu výrobu')}</div></div><div class="hero-visual"><div class="hero-photo"><img src="/assets/unikov-original.jpg" alt="Detail presného obrábania kovu" width="626" height="275" fetchpriority="high"><span class="image-label">MATERIÁL. REMESLO. DETAIL.</span></div><div class="hero-block"><div class="eyebrow">Poctivé strojárstvo</div><div><div class="year">1995<span style="font-size:22px;vertical-align:top;margin-left:5px">↗</span></div><p>Rok, v ktorom sa začal náš príbeh.</p></div><a class="circle-link" href="/o-nas/" aria-label="Spoznať príbeh UNIKOV">↗</a></div></div><div class="hero-bottom"><span>DIELY · PODSKUPINY · KOMPLETNÉ CELKY</span><a href="#co-robime">Objavte UNIKOV ↓</a></div></section><section class="section wrap" id="co-robime"><div class="section-head">${label('01','Čo robíme')}<div class="section-intro"><h2>Od surového kovu<br>k premyslenému <em>celku.</em></h2><p>Vyrábame podľa dodanej výkresovej dokumentácie aj vyvíjame vlastné výrobky. Technické zabezpečenie a vývoj riešime vlastnými kapacitami.</p></div></div><div class="capabilities"><a class="cap-row" href="/vyroba/vyrobne-moznosti/"><span class="cap-no">01</span><h3>Delenie materiálu</h3><p>Rezanie, strihanie a pálenie<br>plameňom, plazmou či laserom.</p><span>↗</span></a><a class="cap-row" href="/vyroba/vyrobne-moznosti/"><span class="cap-no">02</span><h3>Presné obrábanie</h3><p>Sústruženie, CNC sústruženie,<br>frézovanie, vŕtanie a brúsenie.</p><span>↗</span></a><a class="cap-row" href="/vyroba/vyrobne-moznosti/"><span class="cap-no">03</span><h3>Tvarovanie a spájanie</h3><p>Ohýbanie, zváranie<br>a montáž dielov do celkov.</p><span>↗</span></a><a class="cap-row" href="/vyroba/vyrobne-moznosti/"><span class="cap-no">04</span><h3>Povrch a odolnosť</h3><p>Povrchové úpravy kovov<br>a tepelné spracovanie.</p><span>↗</span></a></div><div class="section-action">${link('/vyroba/vyrobne-moznosti/','Všetky možnosti a rozmery')}</div></section><section class="showcase"><div class="wrap"><div class="showcase-top"><div>${label('02','Naša práca')}<h2>Za nás hovoria <em>výrobky.</em></h2></div>${link('/vyrobky/','Celá galéria (32)')}</div><div class="product-preview">${photo('vyrobok24.jpg','Obrábané diely','Detail výroby')}${photo('vyrobok1.jpg','Zváraný celok','Detail výroby')}${photo('vyrobok16.jpg','Oceľové zostavy','Detail výroby')}</div></div></section><section class="section wrap about-strip">${label('03','Ľudia za kovom')}<div><div class="big-statement">Doma v Dubnici.<br>Súčasť strojov <em>v zahraničí.</em></div><div class="about-bottom"><p>Sme súkromná slovenská firma so strojárskou tradíciou. Skúsenosti nášho tímu a spolupráca s partnerskými firmami nám umožňujú reagovať na rôznorodé výrobné zadania.</p>${link('/o-nas/','Viac o UNIKOV-e')}</div></div></section>${cta()}`;}
function about(){return head('O nás','Poctivá práca.<br><em>Od roku 1995.</em>','Z Dubnice nad Váhom dodávame diely, podskupiny a celky pre strojársku výrobu. Naše výrobky sú súčasťou strojov a zariadení zahraničných firiem.')+`<div class="wrap prose-layout"><aside>${label('01','O firme')}</aside><div class="prose"><h2>Strojárstvo máme blízko.</h2><p>UNIKOV, s.r.o. je súkromná firma založená v roku 1995 v regióne so silnou strojárskou tradíciou. Zameriavame sa na výrobu dielov, podskupín a kompletných celkov. V našom tíme pracujú zámočníci, zvárači, sústružníci, frézari a technici.</p><div class="fact-strip"><div><strong>1995</strong><span>Rok založenia</span></div><div><strong>25</strong><span>Pracovníkov podľa firemného profilu</span></div><div><strong>SK</strong><span>Dubnica nad Váhom</span></div></div><p>Dobré kontakty s partnerskými firmami rozširujú naše reálne kapacity. Kvalifikovaný tím a strojové vybavenie tvoria základ kvality, produktivity práce a ďalšieho rozvoja.</p><h2>Pre techniku, ktorá sa hýbe.</h2><div class="sectors"><div>Dopravná a manipulačná technika</div><div>Skladová technika</div><div>Automobilová technika<small>Diely pre cisternové a nákladné vozidlá, prívesy a návesy.</small></div><div>Šachtová a kanálová technika</div><div>Stavebníctvo a priemysel<small>Zábradlia a súvisiace kovové výrobky.</small></div><div>Stroje a kompletné linky</div></div><h2>Váš výkres. Naše skúsenosti.</h2><p>Vyrábame podľa dodaných výkresov aj vlastné výrobky. Technické zabezpečenie výroby a vývoj organizujeme vlastnými kapacitami. Pri cenách a termínoch sa snažíme čo najviac priblížiť požiadavkám zákazníka.</p><p>Vlastné finančné zdroje nám umožňujú udržiavať dostatočné skladové zásoby a pružne reagovať na požiadavky. Vieme zabezpečiť aj výrobu dielov na sklad s následnými dodávkami podľa potreby. Rastúci počet obchodných partnerov je pre nás potvrdením dlhodobej spolupráce.</p>${link('/certifikaty/','Ako pristupujeme ku kvalite')}</div></div>${cta()}`;}
function subnav(items){return `<nav class="subnav wrap" aria-label="Podstránky">${items.map(([u,t])=>`<a href="${u}" class="${path===u?'active':''}" ${path===u?'aria-current="page"':''}>${t}</a>`).join('')}</nav>`;}
const productNav=()=>subnav([['/vyrobky/','Zákazková výroba'],['/vyrobky/vlastne-vyrobky/','Vlastné výrobky']]);
function products(own=false){return head('Výrobky',own?'Vlastná myšlienka.<br><em>Vlastný výrobok.</em>':'Každý diel má<br><em>svoje miesto.</em>',own?'Vývoj vlastných výrobkov a technické zabezpečenie riešime vlastnými kapacitami.':'Výber dielov a zostáv z našej zákazkovej výroby. 32 ukážok zákazkovej výroby na jednom mieste.')+productNav()+(own?`<section class="wrap prose-layout">${label('','Vlastné výrobky')}<div class="prose"><h2>Od návrhu k realizácii.</h2><p>Popri výrobe podľa dodaných výkresov sa zaoberáme aj vývojom a výrobou vlastných výrobkov. Konkrétne možnosti s vami radi prejdeme podľa vášho zadania.</p>${link('/kontakt/','Spýtať sa na vlastné výrobky')}</div></section>`:`<div class="wrap"><div class="gallery-toolbar"><p>32 fotografií · Kliknutím zobrazíte detail</p><label><span class="skip">Poradie fotografií</span><select id="gallery-sort" aria-label="Poradie fotografií"><option value="asc">Od prvého výrobku</option><option value="desc">Od posledného výrobku</option></select></label></div><div id="product-grid" class="gallery-grid">${productGrid()}</div></div>`)+cta();}
function productGrid(desc=false){return Array.from({length:32},(_,i)=>desc?32-i:i+1).map(n=>photo(`vyrobok${n}.jpg`,`Výrobok ${String(n).padStart(2,'0')}`,'UNIKOV')).join('');}
const productionNav=()=>subnav([['/vyroba/','Strojový park'],['/vyroba/vyrobne-moznosti/','Výrobné možnosti'],['/vyroba/fotogaleria/','Fotogaléria'],['/vyroba/logistika/','Logistika']]);
const machineGroups=[['Sústruhy',[['SV 18 RA','2'],['SN 40','1'],['SN 50','1']]],['CNC sústruhy',[['SBL 500','1'],['Gildemeister','1']]],['Frézy',[['F 3 AV','1'],['F 5 AV','1'],['F 3 AH','1']]],['Vŕtačky',[['VS 20','2'],['VS 32 B','2'],['VR 4','1']]],['Píly',[['Privatex','1'],['CNC Pegas','2']]],['Zváračky',[['Zváracie zariadenia','2']]]];
const processGroups=[['Delenie materiálu',[['Rezanie','Priemer','400 mm'],['Strihanie plechov','Hrúbka / šírka','12 / 2 000 mm'],['Pálenie plameňom','Hrúbka / tabuľa','120 mm / 2 000 × 6 000 mm'],['Pálenie plazmou','Hrúbka / tabuľa','15 mm / 2 000 × 6 000 mm'],['Pálenie laserom','Hrúbka / tabuľa','10 mm / 1 500 × 3 000 mm']]],['Obrábanie',[['Sústruženie','Priemer / dĺžka','500 / 1 500 mm'],['CNC sústruženie','Priemer / dĺžka','250 / 350 mm'],['Frézovanie','Rozmery','300 × 300 × 2 000 mm'],['Vŕtanie','Priemer / závity','50 mm / M 40, G 2″'],['Ozubené kolesá','Priemer','300 mm'],['Reťazové kolesá','Priemer','300 mm'],['Brúsenie na guľato','Priemer','100 mm'],['Brúsenie na plocho','Rozmery','150 × 400 mm']]],['Ohýbanie',[['Ohýbanie','Hrúbka / šírka','12 / 2 500 mm']]],['Zváranie',[['Zvárané diely','Hmotnosť','200 kg'],['Zvárané diely','Rozmery','1 500 × 1 500 × 2 000'],['Ochranná atmosféra','Plyny','CO₂, argón, zmes']]]];
function production(type='machines'){
const titles={machines:['Stroje, za ktorými<br>stoja <em>skúsenosti.</em>','Sústruženie, frézovanie, vŕtanie, delenie aj zváranie. Spoznajte technické zázemie našej výroby.'],process:['Možnosti v každom<br><em>rozmere.</em>','Od delenia materiálu po finálnu montáž. Prehľad technológií a maximálnych výrobných parametrov.'],gallery:['Pohľad priamo<br><em>do výroby.</em>','Strojové vybavenie a pracovné prostredie vo firemnej fotogalérii UNIKOV.'],logistics:['Hotový diel.<br><em>Doručený správne.</em>','Výroba sa nekončí pri stroji. Zabezpečujeme balenie, označovanie dielov, skladovanie aj dopravu.']};
let body='';
if(type==='machines')body=`<div class="wrap data-section">${machineGroups.map(([t,rows])=>dataGroup(t,table(['Stroj / typ','Počet kusov'],rows))).join('')}<p class="data-note">Prehľad strojového vybavenia podľa firemného webu. Dostupnosť konkrétnej kapacity a aktuálny termín vám potvrdíme pri dopyte.</p></div>`;
if(type==='process')body=`<div class="wrap data-section">${processGroups.map(([t,rows])=>dataGroup(t,table(['Technológia','Parameter','Maximum / možnosti'],rows))).join('')}${dataGroup('Povrchové úpravy',table(['Úprava','Možnosti'],[['Pieskovanie','Povrchová príprava'],['Lakovanie','Mokré, dvojzložkové a práškové'],['Zinkovanie','Galvanické'],['Ďalšie úpravy','Chromátovanie, čiernenie, fosfátovanie']]))}${dataGroup('Tepelné spracovanie','<ul class="simple-list"><li>Kalenie</li><li>Nitridovanie</li></ul>')}${dataGroup('Montáž','<ul class="simple-list"><li>Montáž dielov, podskupín a celkov.</li></ul>')}<p class="data-note">Uvedené hodnoty predstavujú maximálne parametre podľa firemných podkladov. Pri rozmeroch zváraných dielov firemné podklady jednotku neuvádzajú. Vhodnosť technológie a realizáciu konkrétneho dielu potvrdíme podľa výkresovej dokumentácie.</p></div>`;
if(type==='gallery')body=`<div class="wrap"><div class="gallery-toolbar"><p>19 fotografií · Kliknutím zobrazíte detail</p></div><div class="gallery-grid">${productionImages.map((f,i)=>photo(f,`Výroba ${String(i+1).padStart(2,'0')}`,'Strojový park')).join('')}</div></div>`;
if(type==='logistics')body=`<div class="wrap data-section">${dataGroup('Doprava',table(['Vozidlo','Nosnosť na vozidlo'],[['Malé auto','600 kg'],['Malé auto','1 500 kg'],['Veľké auto','5 000 kg']]))}${dataGroup('Balenie','<ul class="simple-list"><li>Drevené europalety</li><li>Neštandardné palety</li><li>Kartónové krabice</li></ul>')}${dataGroup('Označenie a sklad','<ul class="simple-list"><li>Označovanie dielov</li><li>Skladovanie</li><li>Výroba dielov na sklad a dodávky podľa potreby zákazníka</li></ul>')}</div>`;
return head('Výroba',...titles[type])+productionNav()+body+cta();}
function quality(){return head('Kvalita','Kvalita vzniká<br><em>v detailoch.</em>','Kvalifikovaný tím, kontrola výrobkov a vlastný systém riadenia kvality. Základ práce, za ktorou si stojíme.')+qualityNav()+`<div class="wrap prose-layout"><aside>${label('','Náš prístup')}<div class="quality-mark" aria-hidden="true"></div></aside><div class="prose"><h2>Kontrola ako súčasť výroby.</h2><p>Výrobky kontrolujeme podľa vlastného firemného systému riadenia kvality. Tento systém podľa firemného profilu zabezpečuje kvalitu výrobkov na úrovni požadovaných štandardov DIN a ISO.</p><p>Spoločnosť podľa zverejnených firemných informácií nemá certifikát podľa ISO ani DIN. Požiadavky na kvalitu, kontrolu a dokumentáciu preto vždy prejdeme pri konkrétnom zadaní.</p><div class="notice">Potrebujete pri dodávke splniť konkrétnu normu alebo doložiť dokumentáciu? Pošlite nám požiadavky spolu s výkresom a dohodnime si podmienky realizácie.</div><h2>Certifikáty a fotogaléria</h2><p>Pozrite si meraciu techniku v našej fotogalérii. V sekcii certifikátov nie sú zverejnené žiadne dokumenty. Aktuálne podklady si môžete vyžiadať priamo u nás.</p>${link('/certifikaty/fotogaleria1/','Fotogaléria meracej techniky')}<br>${link('/kontakt/','Prejsť požiadavky na kvalitu')}</div></div>${cta()}`;}
const qualityNav=()=>subnav([['/certifikaty/','Riadenie kvality'],['/certifikaty/fotogaleria1/','Meracia technika']]);
function qualityGallery(){return head('Kvalita / Fotogaléria','Presnosť začína<br><em>meraním.</em>','Pohľad na meraciu techniku vo firme UNIKOV.')+qualityNav()+`<div class="wrap"><div class="gallery-toolbar"><p>6 fotografií · Kliknutím zobrazíte detail</p></div><div class="gallery-grid">${Array.from({length:6},(_,i)=>photo(`meradlo${i+1}.jpg`,`Meracia technika ${String(i+1).padStart(2,'0')}`,'Kvalita')).join('')}</div></div>`+cta();}
function news(){return head('Novinky','Priestor pre<br><em>nové veci.</em>','Správy a informácie z UNIKOV-u.')+`<section class="wrap empty-state"><span class="news-symbol" aria-hidden="true">✳</span><div><h2>Aktuálne bez noviniek.</h2><p>V tejto chvíli nie sú zverejnené žiadne novinky. Naše výrobky a možnosti výroby si môžete prezrieť už teraz.</p>${link('/vyrobky/','Pozrieť si výrobky')}</div></section>${cta()}`;}
function contact(){return head('Kontakt','Dobrý výsledok začína<br><em>rozhovorom.</em>','Pošlite nám svoje zadanie alebo sa ozvite telefonicky. Radi s vami prejdeme možnosti spolupráce.')+`<div class="wrap"><section class="contact-layout"><div class="contact-details">${label('','Sme vám k dispozícii')}<h2 style="margin-top:28px">UNIKOV, s.r.o.</h2><a class="large-link" href="mailto:unikov@unikov.sk">unikov@unikov.sk ↗</a><a class="large-link" href="tel:+421424423371">+421 42 442 33 71</a><a href="tel:+421424420149">+421 42 442 01 49</a><address>Andreja Kmeťa 358/2<br>018 41 Dubnica nad Váhom<br>Slovenská republika</address>${link('https://www.google.com/maps/search/?api=1&query=UNIKOV+Andreja+Kme%C5%A5a+358%2F2+Dubnica+nad+V%C3%A1hom','Zobraziť trasu na mape')}</div><div class="contact-panel"><h2>Čo pre vás vyrobíme?</h2><p>Napíšte nám základné informácie. Výkresovú dokumentáciu môžete priložiť priamo v e-maile.</p><form class="contact-form" id="inquiry"><label for="name">Meno / spoločnosť</label><input id="name" name="name" autocomplete="organization" placeholder="Vaše meno alebo názov firmy" required maxlength="160"><label for="email">Váš e-mail</label><input id="email" name="email" type="email" autocomplete="email" placeholder="vas@email.sk" required maxlength="200"><label for="message">O vašom zadaní</label><textarea id="message" name="message" placeholder="Aký diel potrebujete, v akom množstve a termíne?" required maxlength="6000"></textarea><button class="solid-button" type="submit">Pripraviť e-mailový dopyt <span>↗</span></button><p class="form-note">Otvorí sa vaša e-mailová aplikácia s pripravenou správou. Správu odošlete až v nej. Údaje sa na tomto webe neukladajú.</p><div class="form-result" role="status"></div></form></div></section><section class="legal-grid"><div><h2>Firemné údaje</h2><dl><div><dt>Obchodné meno</dt><dd>UNIKOV, s.r.o.</dd></div><div><dt>IČO</dt><dd>31631312</dd></div><div><dt>IČ DPH</dt><dd>SK2020437661</dd></div><div><dt>Obchodný register</dt><dd>Okresný súd Trenčín, vložka č. 3065/R</dd></div><div><dt>Daňový úrad</dt><dd>Dubnica nad Váhom</dd></div></dl></div><div><h2>Bankové spojenie</h2><dl><div><dt>Banka</dt><dd>Slovenská sporiteľňa, Trenčín</dd></div><div><dt>Číslo účtu</dt><dd>0270472550/0900</dd></div><div><dt>IBAN</dt><dd>Vyžiadajte si aktuálne platobné údaje.</dd></div></dl><p class="form-note">Bankové spojenie je prevzaté z firemného webu. Pred platbou si aktuálne údaje potvrďte priamo s firmou.</p></div></section></div>`;}
function footer(){return `<div class="footer wrap"><div class="footer-grid"><a class="brand" href="/" aria-label="UNIKOV — úvod">unikov<span class="brand-dot">.</span></a><div><div class="small-label">Slovenská strojárska výroba</div><p>UNIKOV, s.r.o.<br>Andreja Kmeťa 358/2<br>018 41 Dubnica nad Váhom</p></div><div class="footer-contact"><div><div class="small-label">Buďme v kontakte</div><a href="mailto:unikov@unikov.sk">unikov@unikov.sk ↗</a><a href="tel:+421424423371">+421 42 442 33 71</a><a href="tel:+421424420149">+421 42 442 01 49</a></div><div><div class="small-label">Objavte viac</div><a href="/vyroba/">Výroba</a><a href="/certifikaty/">Kvalita</a><a href="/kontakt/">Kontakt</a></div></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} UNIKOV, s.r.o.</span><span>S rešpektom k materiálu. Od roku 1995.</span><a href="#main">Späť hore ↑</a></div></div>`;}
let path;
const normalize = p => p==='/'?'/':p.replace(/\/+$/,'')+'/';
function render(scroll=true){
path=normalize(location.pathname);
const aliases={'/o-nas/o-nas/':'/o-nas/','/vyrobky/vyrobky/':'/vyrobky/','/vyroba/vyroba/':'/vyroba/','/certifikaty/certifikaty/':'/certifikaty/','/certifikaty/certifikaty1/':'/certifikaty/','/kontakt/kontakt/':'/kontakt/','/novinky/novinky/':'/novinky/'};
path=aliases[path]||path;
const routes={'/':[home,'Presnosť má svoj tvar'],'/o-nas/':[about,'O nás'],'/vyrobky/':[()=>products(false),'Výrobky'],'/vyrobky/vlastne-vyrobky/':[()=>products(true),'Vlastné výrobky'],'/vyroba/':[()=>production('machines'),'Strojový park'],'/vyroba/vyrobne-moznosti/':[()=>production('process'),'Výrobné možnosti'],'/vyroba/fotogaleria/':[()=>production('gallery'),'Fotogaléria výroby'],'/vyroba/logistika/':[()=>production('logistics'),'Logistika'],'/certifikaty/':[quality,'Kvalita'],'/certifikaty/fotogaleria1/':[qualityGallery,'Meracia technika'],'/novinky/':[news,'Novinky'],'/kontakt/':[contact,'Kontakt']};
const selected=routes[path];
$('#main').innerHTML=selected?selected[0]():head('Stránka sa nenašla','Tento diel<br><em>tu chýba.</em>')+`<div class="wrap section">${link('/','Späť na úvod')}</div>`;
document.title=`UNIKOV — ${selected?selected[1]:'Stránka sa nenašla'}`;
$('#footer').innerHTML=footer();
document.querySelectorAll('.desktop-nav a').forEach(a=>{const active=path.startsWith(normalize(new URL(a.href).pathname));a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});
$('#mobile-nav').hidden=true;$('.menu-toggle').setAttribute('aria-expanded','false');$('.menu-toggle span').textContent='＋';
if(scroll){window.scrollTo(0,0);$('#main').setAttribute('tabindex','-1');$('#main').focus({preventScroll:true})}
bindPhotos();
$('#gallery-sort')?.addEventListener('change',e=>{$('#product-grid').innerHTML=productGrid(e.target.value==='desc');bindPhotos()});
$('#inquiry')?.addEventListener('submit',e=>{e.preventDefault();const form=new FormData(e.target), name=form.get('name').trim(),email=form.get('email').trim(),message=form.get('message').trim();if(!name||!message)return;const subject=`Dopyt na výrobu — ${name}`;const body=`Dobrý deň,\n\n${message}\n\n${name}\n${email}\n\n(Výkresovú dokumentáciu, prosím, priložte k tomuto e-mailu.)`;const href=`mailto:unikov@unikov.sk?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;location.href=href;const result=$('.form-result');result.replaceChildren(document.createTextNode('Dopyt je pripravený. Ak sa e-mailová aplikácia neotvorila, '));const a=document.createElement('a');a.href=href;a.textContent='otvorte správu znova';a.style.textDecoration='underline';result.append(a);});
}
function bindPhotos(){gallery=[...document.querySelectorAll('[data-photo]')];gallery.forEach((b,i)=>{b.addEventListener('click',()=>{currentImage=i;returnFocus=b;updateImage();$('#lightbox').showModal()})})}
function updateImage(){const b=gallery[currentImage];$('#lightbox-image').src=root+b.dataset.photo;$('#lightbox-image').alt=b.dataset.caption;$('#lightbox-caption').textContent=`${b.dataset.caption} · ${currentImage+1} / ${gallery.length}`;}
function advance(n){currentImage=(currentImage+n+gallery.length)%gallery.length;updateImage()}
$('.lightbox-close').addEventListener('click',()=>$('#lightbox').close());
$('.lightbox-prev').addEventListener('click',()=>advance(-1));$('.lightbox-next').addEventListener('click',()=>advance(1));
$('#lightbox').addEventListener('keydown',e=>{if(e.key==='ArrowRight')advance(1);if(e.key==='ArrowLeft')advance(-1)});
$('#lightbox').addEventListener('close',()=>returnFocus?.focus());
$('#lightbox').addEventListener('click',e=>{if(e.target===$('#lightbox'))$('#lightbox').close()});
$('.menu-toggle').addEventListener('click',()=>{const open=$('.menu-toggle').getAttribute('aria-expanded')==='true';$('.menu-toggle').setAttribute('aria-expanded',String(!open));$('.menu-toggle span').textContent=open?'＋':'−';$('#mobile-nav').hidden=open});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#mobile-nav').hidden){$('#mobile-nav').hidden=true;$('.menu-toggle').setAttribute('aria-expanded','false');$('.menu-toggle span').textContent='＋';$('.menu-toggle').focus()}});
document.addEventListener('click',e=>{const a=e.target.closest('a');if(!a||e.ctrlKey||e.metaKey||e.shiftKey||e.altKey||e.button>0||a.target||a.hasAttribute('download'))return;const u=new URL(a.href,location.href);if(u.origin===location.origin&&u.pathname!==location.pathname&&!u.hash){e.preventDefault();history.pushState({},'',u.pathname);render();}});
window.addEventListener('popstate',()=>render());render(false);
